using Godot;
using System;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class ImageWorkspaceUiOperations
{
    private static GDScript RepairBridge()=>GD.Load<GDScript>("res://Workspaces/ImageWorkspace/image_repair_toolbar.gd");
    private static GodotObject RepairTool(Control workspace)=>Canvas(workspace).Get("repair_tool").AsGodotObject();
    private static Control? WorkspaceAncestor(Node node){for(Node? current=node;current!=null;current=current.GetParent()){var script=current.GetScript().As<Script>();while(script!=null){if(script.ResourcePath=="res://Workspaces/ImageWorkspace/image_workspace.gd")return current as Control;script=script.GetBaseScript();}}return null;}
    public void repair_number(Node parent,string caption,double value,double minimum,double maximum,double step,Variant changed)
    {
        var label=new Label{Text=caption};label.AddThemeFontSizeOverride("font_size",11);parent.AddChild(label);var number=NewNumber(parent,value,minimum,maximum,step,65);var bridge=RepairBridge();bridge.Call("_connect",number,"value_changed",changed);bridge.Call("_connect",number,"preview_changed",changed);
    }
    public void repair_setting(Node parent,string caption,double value,Variant changed)
    {
        var label=new Label{Text=caption,TooltipText=caption};label.AddThemeFontSizeOverride("font_size",11);parent.AddChild(label);var slider=new HSlider{MinValue=0,MaxValue=1,Step=.01,Value=value,CustomMinimumSize=new Vector2(66,28),TooltipText=caption};parent.AddChild(slider);RepairBridge().Call("_connect",slider,"value_changed",changed);
    }
    public void repair_option(Node parent,GArray captions,GArray ids,string current,Variant changed)
    {
        var workspace=WorkspaceAncestor(parent);if(workspace==null)return;var bridge=RepairBridge();Picker(workspace,parent,"RepairOption","CHOOSE",ids,captions,current,index=>{bridge.Call("_choice",changed,ids[index].AsString());workspace.Call("_refresh_context");});
    }
    public void repair_options(Control workspace)
    {
        var tool=RepairTool(workspace);var config=tool.Get("config").AsGodotDictionary();var popup=new PopupPanel();workspace.AddChild(popup);popup.AddThemeStyleboxOverride("panel",workspace.Call("_box",new Color("152330"),new Color("456476"),10,12).As<StyleBox>());var column=new VBoxContainer{CustomMinimumSize=new Vector2(360,240)};popup.AddChild(column);column.AddChild(new Label{Text="REPAIR · ADVANCED"});var ranges=new System.Collections.Generic.List<(string Key,double Low,double High,double Step)>{("texture_preservation",0,2,.01),("search_radius",1,12,1),("patch_size",3,64,1),("boundary_feather",0,16,.1)};if(tool.Get("repair_source").AsString()=="sample"){ranges.RemoveAll(value=>value.Key is "search_radius" or "patch_size");ranges.Add(("sample_size",4,512,1));}if(tool.Get("repair_method").AsString()=="exact"&&tool.Get("repair_source").AsString()=="sample")ranges.RemoveAll(value=>value.Key=="texture_preservation");foreach(var range in ranges){string key=range.Key;var row=new HBoxContainer();column.AddChild(row);repair_number(row,key.Replace("_"," ").Capitalize(),Get(config,key,range.Low).AsDouble(),range.Low,range.High,range.Step,Callable.From<double>(value=>tool.Call("configure",key,value)));}foreach(var entry in new[]{("Pressure controls size","pressure"),("Clip to source opacity","clip_alpha"),("Repair on a new layer","new_layer")}){string key=entry.Item2;var check=new CheckButton{Text=entry.Item1,ButtonPressed=Get(config,key,false).AsBool()};column.AddChild(check);check.Toggled+=value=>tool.Call("configure",key,value);}ActionButton(workspace,column,"Done",popup.Hide,"Keep repair settings","check");popup.PopupHide+=popup.QueueFree;popup.PopupCentered();
    }
    public void repair_build(Control workspace)
    {
        var tool=RepairTool(workspace);var config=tool.Get("config").AsGodotDictionary();var mode=Group(workspace,"REPAIR","repair");var item=workspace.Call("_main_layer").As<Resource>();if(item!=null&&item.Get("properties").AsGodotDictionary().TryGetValue("texture_material",out var material)&&IsImageScript(material,"res://Workspaces/ImageWorkspace/texture_material.gd")&&tool.Get("main_mode").AsString()=="repair")ActionButton(workspace,mode,"Bake material",()=>workspace.Call("rasterize_selected"),"Bake this material before repairing its pixels","check");if(item!=null&&(item.Get("kind").AsString() is not "image" and not "paint" and not "basic"||item.Get("warp").AsGodotObject()!=null)){bool warp=item.Get("warp").AsGodotObject()!=null;ActionButton(workspace,mode,warp?"Bake warp":"Rasterize",()=>{if(item.Get("warp").AsGodotObject()!=null)warp_bake(workspace);else workspace.Call("rasterize_selected");},"Prepare this layer for pixel editing, with undo/redo","layers");}tool.Set("main_mode","repair");repair_option(mode,new GArray{"Nearby","Sample"},new GArray{"nearby","sample"},tool.Get("repair_source").AsString(),Callable.From<string>(value=>{tool.Set("repair_source",value);config["source_mode"]=value=="nearby"?"nearby":"manual";tool.Set("mode",value=="nearby"?"spot":"heal");}));var brush=Group(workspace,"BRUSH","brush");repair_number(brush,"Size",config["size"].AsDouble(),2,1024,1,Callable.From<double>(value=>tool.Call("configure","size",value)));repair_setting(brush,"Hardness",config["hardness"].AsDouble(),Callable.From<double>(value=>tool.Call("configure","hardness",value)));repair_setting(brush,"Strength",config["strength"].AsDouble(),Callable.From<double>(value=>tool.Call("configure","strength",value)));ActionButton(workspace,brush,"More",()=>repair_options(workspace),"Repair quality, matching and source settings","values");workspace.Call("_next_toolbar_row");var context=Group(workspace,"CONTEXT","picker");if(tool.Get("repair_source").AsString()=="sample"){ActionButton(workspace,context,"Sample source",()=>{tool.Set("pick_source",true);workspace.Get("status").As<Label>().Text="Click clean source pixels; then paint the repair. Alt-click also samples.";},"Choose the replacement source","picker");repair_option(context,new GArray{"Natural Heal","Exact Copy"},new GArray{"natural","exact"},tool.Get("repair_method").AsString(),Callable.From<string>(value=>tool.Set("repair_method",value)));repair_option(context,new GArray{"Current layer","Visible layers"},new GArray{"current","visible"},config["sample_mode"].AsString(),Callable.From<string>(value=>config["sample_mode"]=value));var aligned=new CheckButton{Text="Aligned",ButtonPressed=config["aligned"].AsBool()};context.AddChild(aligned);aligned.Toggled+=value=>{config["aligned"]=value;tool.Set("_has_alignment",false);};}var actions=Group(workspace,"SELECTION","mask");ActionButton(workspace,actions,"Repair Selection",()=>GD.Load<GDScript>("res://Workspaces/ImageWorkspace/texture_repair_ui.gd").Call("_fill_and_finish",tool),"Apply to the entire active selection with undo/redo","fill");var selection=new CheckButton{Text="Selection only",ButtonPressed=config["selection_only"].AsBool()};actions.AddChild(selection);selection.Toggled+=value=>config["selection_only"]=value;foreach(var group in new[]{brush,context})foreach(var node in group.FindChildren("*","SpinBox",true,false)){var number=(SpinBox)node;number.Connect("drag_committed",Callable.From<double>(_=>workspace.Call("_commit")));number.ValueChanged+=_=>workspace.Call("_commit");number.Connect("drag_cancelled",Callable.From(()=>{number.EmitSignal("preview_changed",number.Value);workspace.Call("_cancel");}));}
    }
    private static bool IsImageScript(Variant value,string path){if(value.VariantType!=Variant.Type.Object||value.AsGodotObject() is not Resource resource)return false;var script=resource.GetScript().As<Script>();while(script!=null){if(script.ResourcePath==path||script.ResourcePath==LegacyResourceLoader.NativeScriptPath(path))return true;script=script.GetBaseScript();}return false;}
    public Resource repair_pattern_property()
    {
        var property=new ActorProperty();var extensions=GD.Load<GDScript>("res://Workspaces/ImageWorkspace/image_workspace.gd").GetScriptConstantMap()["IMAGE_EXTENSIONS"].AsGodotArray().Duplicate();extensions.Add("tres");extensions.Add("res");property.Set("options",new Settings{["extensions"]=extensions,["native_resource_types"]=new GArray{"KiwiImagePatternPreset","Texture2D"},["file_picker"]=true});return property;
    }
    public void load_repair_pattern(Control workspace,string chosen)
    {
        if(chosen.Length==0||chosen=="::empty-resource::")return;var tool=RepairTool(workspace);if(chosen.GetExtension() is "tres" or "res"){var resource=ResourceLoader.Load(chosen);if(IsImageScript(resource,"res://Workspaces/ImageWorkspace/image_pattern_preset.gd")&&resource.Get("texture").AsGodotObject()!=null){tool.Set("source_image",resource.Get("texture").As<Texture2D>().GetImage());tool.Get("config").AsGodotDictionary().Merge(resource.Get("settings").AsGodotDictionary(),true);var recipe=resource.Get("recipe").As<Resource>();if(recipe!=null){using var recipes=new ImageProceduralTextureOperations();tool.Set("recipe",recipes.copy_recipe(recipe));}}else if(resource is Texture2D texture)tool.Set("source_image",texture.GetImage());}else{var image=Image.LoadFromFile(chosen);tool.Set("source_image",image==null?default(Variant):Variant.From(image));}var source=tool.Get("source_image").As<Image>();if(source!=null){tool.Set("source_area",new Rect2I(Vector2I.Zero,source.GetSize()));tool.Set("pattern_path",chosen);tool.Get("config").AsGodotDictionary()["source_mode"]="manual";workspace.Call("_refresh_context");}
    }
    public Settings prepare_repair_pattern_save(Control workspace)
    {
        var tool=RepairTool(workspace);if(tool.Get("source_image").AsGodotObject()==null){workspace.Get("status").As<Label>().Text="Sample a texture or load a pattern first";return new Settings();}return new Settings{["tool"]=tool};
    }
    public void complete_repair_pattern_save(Control workspace,Settings request,Settings destination)
    {
        if(Get(destination,"cancelled",true).AsBool()||!GodotObject.IsInstanceValid(workspace))return;var tool=request["tool"].AsGodotObject();var preset=new KiwiImagePatternPreset();var config=tool.Get("config").AsGodotDictionary();var settings=config.Duplicate(true);preset.Set("settings",settings);var area=tool.Get("source_area").AsRect2I();using var sample=tool.Get("source_image").As<Image>().GetRegion(area);var points=tool.Get("source_points").AsVector2Array();string shape=Get(config,"sample_shape","rectangle").AsString();for(int y=0;y<sample.GetHeight();y++)for(int x=0;x<sample.GetWidth();x++)if(!ImageTextureSynthesisOperations.Inside((Vector2)(area.Position+new Vector2I(x,y))+Vector2.One*.5f,area,shape,points))sample.SetPixel(x,y,Colors.Transparent);settings["sample_shape"]="rectangle";preset.Set("texture",ImageTexture.CreateFromImage(sample));if(tool.Get("mode").AsString()=="procedural"){using var recipes=new ImageProceduralTextureOperations();preset.Set("recipe",recipes.copy_recipe(tool.Get("recipe").As<Resource>()));}ResourceSaver.Save(preset,destination["path"].AsString());RepairBridge().Call("_refresh_filesystem");
    }
}
